import{_ as i,o as a,c as o,ae as t}from"./chunks/framework.qNV68s4p.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1776334221000}'),r={name:"guide/faq.md"};function l(n,e,d,c,s,p){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="is-sweeteditor-a-basictextfield-enhancement" tabindex="-1">Is SweetEditor a <code>BasicTextField</code> enhancement? <a class="header-anchor" href="#is-sweeteditor-a-basictextfield-enhancement" aria-label="Permalink to &quot;Is SweetEditor a `BasicTextField` enhancement?&quot;">​</a></h2><p>No.</p><p>SweetEditor is a dedicated editor architecture built on a native editor kernel with a Compose Multiplatform wrapper.</p><h2 id="does-sweeteditor-depend-on-native-code" tabindex="-1">Does SweetEditor depend on native code? <a class="header-anchor" href="#does-sweeteditor-depend-on-native-code" aria-label="Permalink to &quot;Does SweetEditor depend on native code?&quot;">​</a></h2><p>Yes.</p><p>The project is built around a native editor core and a Kotlin wrapper layer.</p><h2 id="what-is-the-native-core-based-on" tabindex="-1">What is the native core based on? <a class="header-anchor" href="#what-is-the-native-core-based-on" aria-label="Permalink to &quot;What is the native core based on?&quot;">​</a></h2><p>The native core used by this project is based on:</p><ul><li><a href="https://github.com/FinalScave/OpenSweetEditor" target="_blank" rel="noreferrer">FinalScave/OpenSweetEditor</a></li></ul><h2 id="which-platforms-are-supported" tabindex="-1">Which platforms are supported? <a class="header-anchor" href="#which-platforms-are-supported" aria-label="Permalink to &quot;Which platforms are supported?&quot;">​</a></h2><p>Current targets include:</p><ul><li>Android</li><li>iOS</li><li>JVM Desktop</li><li>JS</li><li>Wasm</li></ul><h2 id="can-i-use-sweeteditor-in-compose-multiplatform-apps" tabindex="-1">Can I use SweetEditor in Compose Multiplatform apps? <a class="header-anchor" href="#can-i-use-sweeteditor-in-compose-multiplatform-apps" aria-label="Permalink to &quot;Can I use SweetEditor in Compose Multiplatform apps?&quot;">​</a></h2><p>Yes.</p><p>That is the primary purpose of <code>editor-compose</code>.</p><h2 id="can-i-customize-syntax-highlighting-and-decorations" tabindex="-1">Can I customize syntax highlighting and decorations? <a class="header-anchor" href="#can-i-customize-syntax-highlighting-and-decorations" aria-label="Permalink to &quot;Can I customize syntax highlighting and decorations?&quot;">​</a></h2><p>Yes.</p><p>Use:</p><ul><li><code>DecorationProvider</code></li><li><code>DecorationUpdate</code></li><li><code>DecorationSet</code></li><li>custom <code>textStyles</code></li></ul><h2 id="can-i-provide-completion-items" tabindex="-1">Can I provide completion items? <a class="header-anchor" href="#can-i-provide-completion-items" aria-label="Permalink to &quot;Can I provide completion items?&quot;">​</a></h2><p>Yes.</p><p>Use:</p><ul><li><code>CompletionProvider</code></li><li><code>CompletionContext</code></li><li><code>CompletionReceiver</code></li></ul><h2 id="does-the-project-support-inline-suggestions-or-copilot-style-ux" tabindex="-1">Does the project support inline suggestions or copilot-style UX? <a class="header-anchor" href="#does-the-project-support-inline-suggestions-or-copilot-style-ux" aria-label="Permalink to &quot;Does the project support inline suggestions or copilot-style UX?&quot;">​</a></h2><p>Yes.</p><p>The Compose layer provides:</p><ul><li><code>InlineSuggestion</code></li><li><code>InlineSuggestionController</code></li><li>inline action bar behavior</li></ul><h2 id="can-i-change-theme-and-typography" tabindex="-1">Can I change theme and typography? <a class="header-anchor" href="#can-i-change-theme-and-typography" aria-label="Permalink to &quot;Can I change theme and typography?&quot;">​</a></h2><p>Yes.</p><p>Use:</p><ul><li><code>rememberEditorAppearance()</code></li><li><code>rememberEditorTheme()</code></li><li><code>EditorFontConfig</code></li><li><code>applyTheme()</code></li><li><code>applySettings()</code></li></ul><h2 id="should-i-re-implement-core-editor-logic-in-kotlin" tabindex="-1">Should I re-implement core editor logic in Kotlin? <a class="header-anchor" href="#should-i-re-implement-core-editor-logic-in-kotlin" aria-label="Permalink to &quot;Should I re-implement core editor logic in Kotlin?&quot;">​</a></h2><p>No.</p><p>The recommended approach is to reuse native core capabilities and keep Kotlin focused on wrapping, state synchronization, and UI integration.</p><h2 id="where-should-platform-specific-code-live" tabindex="-1">Where should platform-specific code live? <a class="header-anchor" href="#where-should-platform-specific-code-live" aria-label="Permalink to &quot;Where should platform-specific code live?&quot;">​</a></h2><p>Platform-specific behavior should stay in the corresponding source set:</p><ul><li><code>androidMain</code></li><li><code>iosMain</code></li><li><code>jvmMain</code></li><li><code>webMain</code></li></ul><h2 id="where-can-i-see-practical-integration-examples" tabindex="-1">Where can I see practical integration examples? <a class="header-anchor" href="#where-can-i-see-practical-integration-examples" aria-label="Permalink to &quot;Where can I see practical integration examples?&quot;">​</a></h2><p>Start with:</p><ul><li><a href="./quick-start">Quick Start</a></li><li><a href="./api-cookbook">API Cookbook</a></li><li><a href="https://github.com/lumkit/SweetEditor-Compose/tree/main/example" target="_blank" rel="noreferrer">Example App</a></li></ul>',41)])])}const m=i(r,[["render",l]]);export{u as __pageData,m as default};
